class Box {
  static label = this.kind;
  static kind = "crate";
  static {
    this.tag = `${this.kind}-1`;
  }
  static describe() {
    return this.tag;
  }
}

const { describe } = Box;
console.log(Box.label);
console.log(Box.describe());
try {
  console.log(describe());
} catch (error) {
  console.log(error.name);
}
console.log(new Box().constructor.kind);
